/**
 * Return the CURRENT installation when this exact project/journal/guard pair is already wired,
 * otherwise install it now.
 *
 * WHY THIS EXISTS: a deployment can be launched before the host materializes its Git worktree
 * (candidate probes do exactly that). Installation at launch then honestly reports "not a Git
 * worktree", and a later direct merge has no hook to record it. A READ path cannot undo the missed
 * merge, but it can repair the wiring before the next ordinary Git operation. This function is
 * idempotent: an existing matching installation is reused instead of rewriting live hooks.
 */
export function ensureDirectDeliveryGuard(
  input: DirectDeliveryGuardInstallInput,
): DirectDeliveryGuardInstallation {
  const repository = resolve(input.repository);
  const gitDir = git(repository, ["rev-parse", "--absolute-git-dir"]);
  if (gitDir === null) return installDirectDeliveryGuard(input);
  const hookDir = resolveHookDir(repository);
  if (hookDir === null) return installDirectDeliveryGuard(input);
  const moduleUrl = input.moduleUrl ?? moduleUrlForThisFile();
  const configPath = join(gitDir, "palimpsest", "direct-delivery.json");
  const guardScript = join(gitDir, "palimpsest", "direct-delivery-guard.mjs");
  let config: Partial<GuardConfig>;
  try {
    config = JSON.parse(readFileSync(configPath, "utf8")) as Partial<GuardConfig>;
  } catch {
    return installDirectDeliveryGuard(input);
  }
  const matches =
    config.schema === DIRECT_DELIVERY_GUARD_SCHEMA &&
    config.projectId === input.projectId &&
    config.repository === repository &&
    config.journalPath === resolve(input.journalPath) &&
    config.orchestrationPath === resolve(input.orchestrationPath) &&
    config.moduleUrl === moduleUrl &&
    typeof config.installationId === "string" &&
    existsSync(guardScript) &&
    ["post-commit", "post-merge"].every((name) => {
      try {
        return readFileSync(join(hookDir, name), "utf8").includes(DIRECT_DELIVERY_GUARD_MARKER);
      } catch {
        return false;
      }
    });
  if (!matches) return installDirectDeliveryGuard(input);
  return Object.freeze({
    installed: true,
    hooks: Object.freeze(["post-commit", "post-merge"]),
    detail: `direct-delivery guard already installed for project ${input.projectId}`,
    installationId: config.installationId,
    dispose: () =>
      disposeGuardInstallation({
        configPath,
        hookDir,
        guardScript,
        installationId: config.installationId!,
      }),
  });
}

